CREATE TABLE technologies (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE projects (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE,
  title VARCHAR(255) NOT NULL, subtitle VARCHAR(255), category VARCHAR(255),
  short_description VARCHAR(1000) NOT NULL, full_description VARCHAR(5000),
  github_url VARCHAR(500), live_url VARCHAR(500), image_url VARCHAR(500),
  status VARCHAR(255), color VARCHAR(255), featured BOOLEAN NOT NULL DEFAULT FALSE, sort_order INTEGER NOT NULL DEFAULT 0,
  problem VARCHAR(3000), solution VARCHAR(3000), challenges VARCHAR(3000), contribution VARCHAR(3000), improvements VARCHAR(3000),
  created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE TABLE project_technologies (project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, technology_id BIGINT NOT NULL REFERENCES technologies(id), position INTEGER NOT NULL, PRIMARY KEY(project_id,position), UNIQUE(project_id,technology_id));
CREATE TABLE project_features (project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, position INTEGER NOT NULL, feature VARCHAR(500), PRIMARY KEY(project_id,position));
CREATE TABLE project_architecture (project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, position INTEGER NOT NULL, step VARCHAR(500), PRIMARY KEY(project_id,position));
CREATE TABLE skills (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category VARCHAR(100) NOT NULL, level VARCHAR(100) NOT NULL, technology_id BIGINT NOT NULL REFERENCES technologies(id), sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE experiences (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(255) NOT NULL, organization VARCHAR(255), description VARCHAR(2000), sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE education (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, institution VARCHAR(255) NOT NULL, degree VARCHAR(255), status VARCHAR(255), location VARCHAR(255));
CREATE TABLE education_focus (education_id BIGINT NOT NULL REFERENCES education(id) ON DELETE CASCADE, position INTEGER NOT NULL, focus VARCHAR(100), PRIMARY KEY(education_id,position));
CREATE TABLE certifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(255) NOT NULL, issuer VARCHAR(255), type VARCHAR(255), credential_id VARCHAR(255));
CREATE TABLE social_links (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, platform VARCHAR(100) NOT NULL UNIQUE, url VARCHAR(500) NOT NULL);
CREATE TABLE contact_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, subject VARCHAR(150) NOT NULL, message VARCHAR(5000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('NEW','READ','REPLIED')));
CREATE INDEX contact_messages_status_created_idx ON contact_messages(status,created_at);
